"use client"

import * as React from "react"
import { cn } from "@/lib/utils"

export interface BentoGridProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode
}

export function BentoGrid({ className, children, ...props }: BentoGridProps) {
  return (
    <div
      className={cn(
        "grid w-full auto-rows-[22rem] grid-cols-3 gap-6",
        className
      )}
      {...props}
    >
      {children}
    </div>
  )
}

export interface BentoCardProps extends React.HTMLAttributes<HTMLDivElement> {
  name: string
  className?: string
  background?: React.ReactNode
  Icon?: React.ElementType
  description: string
  href?: string
  cta?: string
  children?: React.ReactNode
}

export function BentoCard({
  name,
  className,
  background,
  Icon,
  description,
  href,
  cta = "Learn more",
  children,
  ...props
}: BentoCardProps) {
  return (
    <div
      className={cn(
        "group relative col-span-3 flex flex-col justify-between overflow-hidden rounded-2xl",
        // light styles
        "bg-surface border border-border shadow-subtle transition-all duration-300 hover:shadow-floating",
        // dark styles
        "dark:bg-slate-900/50 dark:border-slate-800",
        className
      )}
      {...props}
    >
      <div>{background}</div>
      <div className="pointer-events-none z-10 flex transform-gpu flex-col gap-2 p-6 transition-all duration-300 group-hover:-translate-y-10">
        {Icon && (
          <Icon className="h-10 w-10 origin-left transform-gpu text-fjord transition-all duration-300 ease-in-out group-hover:scale-75" />
        )}
        <h3 className="text-xl font-bold font-display text-ink">{name}</h3>
        <p className="max-w-lg text-body-sm text-muted">{description}</p>
      </div>

      <div
        className={cn(
          "pointer-events-none absolute bottom-0 flex w-full translate-y-10 transform-gpu flex-row items-center p-6 opacity-0 transition-all duration-300 group-hover:translate-y-0 group-hover:opacity-100"
        )}
      >
        {href ? (
          <a
            href={href}
            className="pointer-events-auto inline-flex items-center gap-2 text-xs font-bold text-fjord hover:underline"
          >
            {cta} →
          </a>
        ) : null}
      </div>
      <div className="pointer-events-none absolute inset-0 transition-all duration-300 group-hover:bg-black/[.03] group-hover:dark:bg-neutral-800/10" />
      {children}
    </div>
  )
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
